// CBC mode of operation built on the AES block primitive.
// Mirrors pyaes.AESModeOfOperationCBC behavior: the chaining state is
// kept inside the object, so successive encrypt() calls chain blocks.

import { expandKey, encryptBlock } from './aes.mjs';

export class AESModeOfOperationCBC {
  constructor(key, iv) {
    if (iv.length !== 16) {
      throw new Error('IV must be exactly 16 bytes');
    }
    this._roundKeys = expandKey(key);
    this._lastCipherBlock = Uint8Array.from(iv); // chaining state, starts as IV
  }

  // Encrypt a single 16-byte block, updating the CBC chaining state.
  encrypt(block) {
    if (block.length !== 16) {
      throw new Error('CBC encrypt requires 16-byte blocks');
    }
    const xored = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
      xored[i] = block[i] ^ this._lastCipherBlock[i];
    }
    const cipher = encryptBlock(xored, this._roundKeys);
    this._lastCipherBlock = Uint8Array.from(cipher);
    return cipher;
  }
}

