// Format a byte array exactly like Python's repr() of a bytes object,
// so console.log output matches Python's print(bytes) character by character.
//
// Rules (CPython bytes_repr):
// - Default quote is a single quote; if the data contains a single quote
//   but no double quote, double quotes are used instead.
// - Printable ASCII (0x20..0x7e) is emitted as-is, except backslash and
//   the active quote character, which are backslash-escaped.
// - \t, \n, \r use their short escapes; all other bytes use \xhh.

export function pyBytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const q = String.fromCharCode(quote);

  let out = 'b' + q;
  for (const b of bytes) {
    if (b === quote || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += q;
  return out;
}

