// Minimal command-line parser matching the Python argparse setup:
//   parser.add_argument('--key',  type=str, required=True)
//   parser.add_argument('--iv',   type=str, required=True)
//   parser.add_argument('--data', type=str, required=True)
// Supports both "--name value" and "--name=value" forms, like argparse.

const REQUIRED = ['key', 'iv', 'data'];

export function parseArgs(argv, progName = 'test17.mjs') {
  const values = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg.startsWith('--')) {
      const body = arg.slice(2);
      const eq = body.indexOf('=');
      let name, value;
      if (eq !== -1) {
        name = body.slice(0, eq);
        value = body.slice(eq + 1);
      } else {
        name = body;
        if (i + 1 >= argv.length) {
          usageError(progName, `argument --${name}: expected one argument`);
        }
        value = argv[++i];
      }
      if (!REQUIRED.includes(name)) {
        usageError(progName, `unrecognized arguments: --${name}`);
      }
      values[name] = value;
    } else {
      usageError(progName, `unrecognized arguments: ${arg}`);
    }
  }
  const missing = REQUIRED.filter((n) => !(n in values));
  if (missing.length > 0) {
    usageError(
      progName,
      'the following arguments are required: ' + missing.map((n) => '--' + n).join(', ')
    );
  }
  return values;
}

function usageError(progName, message) {
  // argparse prints usage + error to stderr and exits with code 2.
  console.error(`usage: ${progName} [-h] --key KEY --iv IV --data DATA`);
  console.error(`${progName}: error: ${message}`);
  process.exit(2);
}

