// Entry point — Node.js ESM port of /workspace/dataset/pyaes/test17.py.
// Encrypts 3 blocks of data with AES-128 CBC chaining and prints each
// ciphertext block using Python's bytes repr format.

import { parseArgs } from './lib/args.mjs';
import { AESModeOfOperationCBC } from './lib/cbc.mjs';
import { pyBytesRepr } from './lib/pybytes.mjs';

function encodeUtf8(str) {
  // Equivalent of Python's str.encode() (UTF-8).
  return new Uint8Array(Buffer.from(str, 'utf8'));
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  // Encrypt multiple blocks with CBC
  const aes = new AESModeOfOperationCBC(encodeUtf8(args.key), encodeUtf8(args.iv));
  const data = encodeUtf8(args.data);

  // Encrypt 3 blocks with CBC chaining
  const ciphertexts = [];
  for (let i = 0; i < data.length; i += 16) {
    const block = data.slice(i, i + 16);
    const cipher = aes.encrypt(block);
    ciphertexts.push(cipher);
  }

  // Print all ciphertexts
  for (const cipher of ciphertexts) {
    console.log(pyBytesRepr(cipher));
  }
}

main();

